using Rhino; using Rhino.Commands;
namespace RhinoContextAssist;
public sealed class ContextAssistAnCommand:Command{public override string EnglishName=>"ContextAssistAn";protected override Result RunCommand(RhinoDoc d,RunMode m){var c=ContextAssistPlugIn.Instance?.Controller;if(c is null)return Result.Failure;c.Enabled=true;c.RefreshNow();return Result.Success;}}
public sealed class ContextAssistAusCommand:Command{public override string EnglishName=>"ContextAssistAus";protected override Result RunCommand(RhinoDoc d,RunMode m){var c=ContextAssistPlugIn.Instance?.Controller;if(c is null)return Result.Failure;c.Enabled=false;c.Hide();return Result.Success;}}
public sealed class ContextAssistUmschaltenCommand:Command{public override string EnglishName=>"ContextAssistUmschalten";protected override Result RunCommand(RhinoDoc d,RunMode m){var c=ContextAssistPlugIn.Instance?.Controller;if(c is null)return Result.Failure;c.Enabled=!c.Enabled;if(c.Enabled)c.RefreshNow();else c.Hide();return Result.Success;}}
